using System.Text.Json;
using VisionCore;
using VisionPlugins.DistortionCalibration;
// Controlled failure propagation, not a native nonfinite-input parity claim.
if(DistortionCalibrationRadialLinearAlgebra.Solve(new double[2,2],new double[2]) is not null)throw new Exception("Zero matrix inverse must fail");
bool radialFailed=false;try{DistortionCalibrationRadialFit.FromSeed(new Point2[]{new(0,0),new(1,0),new(0,1),new(1,1)},new Point2[]{new(0,0),new(1,0),new(0,1),new(1,1)},Enumerable.Repeat(double.PositiveInfinity,9).ToArray(),480,400,1);}catch(DistortionCalibrationRadialFitFailure failure){radialFailed=failure.NativeErrorCode==0x1010300b;}
if(!radialFailed)throw new Exception("Failed radial stage must not become a successful earlier-stage value");
Console.WriteLine("Controlled inverse/stage failure propagation passed: 1010300b; no nonfinite native parity claim.");
using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/distortion-calibration-radial-synthetic-evidence.json"));int checks=0,bits=0;double maximum=0;var reports=new List<object>();foreach(var row in evidence.RootElement.GetProperty("cases").EnumerateArray()){var native=row.GetProperty("native");if(native.GetProperty("code").GetInt32()!=1||native.GetProperty("seedCode").GetInt32()!=1)throw new Exception("Original kernel failed");int count=native.GetProperty("count").GetInt32();var bytes=Convert.FromBase64String(row.GetProperty("pointPairsBase64").GetString()!);Point2[] Pairs(int offset)=>Enumerable.Range(0,count).Select(i=>new Point2(BitConverter.ToSingle(bytes,offset+i*8),BitConverter.ToSingle(bytes,offset+i*8+4))).ToArray();var result=DistortionCalibrationRadialFit.FromSeed(Pairs(0),Pairs(count*8),native.GetProperty("seed").EnumerateArray().Select(v=>v.GetDouble()).ToArray(),480,400,1);var expected=native.GetProperty("radial").EnumerateArray().Concat(native.GetProperty("center").EnumerateArray()).Select(v=>(float)v.GetDouble()).ToArray();var actual=result.Radial.Concat(new[]{(float)result.Center.X,(float)result.Center.Y}).ToArray();int exact=expected.Zip(actual).Count(v=>BitConverter.SingleToInt32Bits(v.First)==BitConverter.SingleToInt32Bits(v.Second));bits+=exact;foreach(int field in new[]{0,1,2,4,5}){checks++;if(actual[field]!=expected[field])throw new Exception($"Native radial/center field {field} differs");}double Forward(float[] p,double x,double y,bool horizontal){double dx=x-p[4],dy=y-p[5],r=dx*dx+p[2]*dy*dy,d=horizontal?dx:dy,k=p[horizontal?0:1];return(horizontal?x:y)+k*d*r+d*k*p[3]*r*r;}
 double mapError=0;for(int y=0;y<=400;y+=40)for(int x=0;x<=480;x+=40)foreach(bool horizontal in new[]{false,true})mapError=Math.Max(mapError,Math.Abs(Forward(actual,x,y,horizontal)-Forward(expected,x,y,horizontal)));maximum=Math.Max(maximum,mapError);checks++;if(mapError>1e-6)throw new Exception("Native radial field projection differs by "+mapError);reports.Add(new{kind=native.GetProperty("case").GetInt32(),exact,mapError,result.AcceptedStages,expected,actual});}
Directory.CreateDirectory("analysis/distortion-calibration/radial-verification");File.WriteAllText("analysis/distortion-calibration/radial-verification/report.json",JsonSerializer.Serialize(new{checks,bits,floatFields=48,maximumMapPixelDifference=maximum,scope="Eight source-backed fourteen-variable cases with original kernel seeds; detection/common seed not covered",reports},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Radial fit checks {checks}, float bits {bits}/48, maximum mapped difference {maximum:R} pixels");

